#!/usr/bin/env bash
# shellcheck disable=SC2329
# The library defines helpers a given wizard may not call (shellcheck SC2329), so that check is off for the file.
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill (.claude/skills/wizard/SKILL.md).
# Adapted from Matt Pocock's `wizard` skill (https://github.com/mattpocock/skills, MIT licence;
# see .claude/skills/LICENSE-mattpocock-skills).
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: the same in every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
# Values the wizard keeps go to a Java properties file outside the repo (LoyScan has no .env): by default the user's
# Gradle properties, which the build reads (wiki/workflows/build-and-run.md).
PROPS_FILE="${PROPS_FILE:-$HOME/.gradle/gradle.properties}"
REPO_ROOT=$(git -C "$(dirname "${BASH_SOURCE[0]}")" rev-parse --show-toplevel 2>/dev/null || pwd)
WRITTEN_PROPS=()  # keys written to PROPS_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is an action the human takes.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser: Git Bash on Windows, WSL, Linux, macOS.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N]%s ' "$YELLOW" "$1" "$RESET"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# java_path PATH: a path Java on this machine understands. Git Bash's /c/Users/… becomes C:/Users/… (forward
# slashes, since a backslash is an escape character in a properties file); elsewhere it is unchanged.
java_path() {
  if command -v cygpath >/dev/null 2>&1; then cygpath -m "$1"; else printf '%s' "$1"; fi
}

# inside_repo PATH succeeds when PATH is inside this repository's working tree. A secret there is one `git add`
# from being public, so the wizard refuses such paths.
inside_repo() {
  local dir; dir=$(dirname "$1")
  while [[ ! -d "$dir" ]]; do dir=$(dirname "$dir"); done
  local top; top=$(git -C "$dir" rev-parse --show-toplevel 2>/dev/null) || return 1
  [[ "$(cd "$top" && pwd -P)" == "$(cd "$REPO_ROOT" && pwd -P)" ]]
}

# _existing KEY: current value of property KEY in PROPS_FILE, if any (backslash escapes undone).
_existing() {
  [[ -f "$PROPS_FILE" ]] || return 1
  local line; line=$(grep -F "${1}=" "$PROPS_FILE" | grep -E "^[[:space:]]*${1//./\\.}=" | tail -n1) || return 1
  local value="${line#*=}"
  printf '%s' "${value//\\\\/\\}"
}

# ask VAR "Prompt" [PROPERTY] reads a value into $VAR. Offers PROPERTY's value in
# PROPS_FILE as a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local var="$1" prompt="$2" key="${3:-}" current="" input s=$'\001' e=$'\002' p rc=0
  [[ -n "$key" ]] && current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM${e}[Enter keeps $current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$var" '%s' "$input"
}

# ask_secret VAR "Prompt" [PROPERTY] is like ask, but input is hidden.
ask_secret() {
  local var="$1" prompt="$2" key="${3:-}" current="" input rc=0
  [[ -n "$key" ]] && current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$var" '%s' "$input"
}

# write_property KEY VALUE upserts KEY=VALUE into PROPS_FILE (replaces any existing
# line), escaping backslashes. Idempotent. Refuses a PROPS_FILE inside the repo.
# Creates the file owner-only (on Windows the folder's permissions apply instead).
write_property() {
  local key="$1" value="$2" tmp
  if inside_repo "$PROPS_FILE"; then
    SKIPPED+=("$key: $PROPS_FILE is inside the repo, so nothing was written there")
    warn "refused to write $key into $PROPS_FILE: it is inside the repo"
    return
  fi
  mkdir -p "$(dirname "$PROPS_FILE")"
  [[ -e "$PROPS_FILE" ]] || (umask 077 && : > "$PROPS_FILE")
  tmp=$(mktemp)
  grep -vE "^[[:space:]]*${key//./\\.}=" "$PROPS_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "${value//\\/\\\\}" >> "$tmp"
  cat "$tmp" > "$PROPS_FILE"
  rm -f "$tmp"
  WRITTEN_PROPS+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$PROPS_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh (value on stdin,
# never on the command line). Falls back to a warning if gh isn't ready.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | (cd "$REPO_ROOT" && gh secret set "$name") >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if (cd "$REPO_ROOT" && gh variable set "$name" --body "$value") >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Done%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_PROPS[@]} ))  && note "wrote ${#WRITTEN_PROPS[@]} value(s) to $PROPS_FILE: ${WRITTEN_PROPS[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=1

banner "Example setup"

# ── Example stage: replace with your real steps ───────────────────────────
stage "Example service: API token"
say "We'll get an API token and keep it for local builds and CI."
open_url "https://example.com/settings/tokens"
step "Create a token, then copy it."
ask_secret EXAMPLE_TOKEN "Paste the token:" example.token
write_property example.token "$EXAMPLE_TOKEN"
set_secret EXAMPLE_TOKEN "$EXAMPLE_TOKEN"   # CI needs this one
# ──────────────────────────────────────────────────────────────────────────

finish
}

run_wizard "$@"; exit
